"""Encoding fallback is verified with generated bytes, not a fragile binary fixture."""

import pytest

from data_io import read_csv_robust


def cp1252_bytes():
    text = (
        "temperature_deg\u00b0C;pressure_kPa;replicate\n"
        "20.0;101.3;R1\n25.0;103.8;R1\n30.0;oops;R2\n35.0;108.1;R2\n"
        ";110.4;R3\n45.0;inf;R3\n50.0;114.7;R4\n55.0;117.2;R4\n"
    )
    return text.encode("cp1252")


def test_cp1252_fallback_restores_degree_sign_and_warns(tmp_path):
    path = tmp_path / "cp1252.csv"
    path.write_bytes(cp1252_bytes())
    load = read_csv_robust(path, source_name=path.name)
    assert load.encoding == "cp1252"
    assert load.delimiter == ";"
    assert "temperature_deg\u00b0C" in load.frame.columns
    assert any("not UTF-8" in warning for warning in load.warnings)
    assert len(load.frame) == 8


def test_latin1_fallback_for_a_byte_that_is_not_valid_cp1252(tmp_path):
    path = tmp_path / "latin1.csv"
    # 0x81 is undefined in Python cp1252, so latin-1 must be used.
    path.write_bytes(b"caf\x81;value\n1;2\n")
    load = read_csv_robust(path, source_name=path.name)
    assert load.encoding == "latin-1"
    assert len(load.frame) == 1


def test_utf8_bom_is_reported_only_when_present():
    plain = read_csv_robust(b"a,b\n1,2\n", source_name="plain.csv")
    bom = read_csv_robust(b"\xef\xbb\xbfa,b\n1,2\n", source_name="bom.csv")
    assert plain.encoding == "utf-8"
    assert bom.encoding == "utf-8-sig"


def test_shipped_messy_example_is_valid_utf8_and_still_messy():
    from pathlib import Path

    path = Path(__file__).resolve().parents[1] / "data" / "examples" / "synthetic_messy_semicolon.csv"
    load = read_csv_robust(path, source_name=path.name)
    assert load.encoding == "utf-8"
    assert load.delimiter == ";"
    assert len(load.frame) == 8
    assert not load.warnings


def test_replacement_character_bytes_are_not_silently_reinterpreted():
    # A snapshot can turn 0xB0 into EF BF BD. That must decode as UTF-8 (with
    # the replacement character visible), not be guessed as cp1252.
    path_bytes = b"temperature_deg\xef\xbf\xbdC;pressure\n20.0;101.3\n"
    load = read_csv_robust(path_bytes, source_name="mangled.csv")
    assert load.encoding == "utf-8"
    assert "\ufffd" in load.frame.columns[0]


def test_whitespace_only_input_is_rejected():
    from data_io import DataImportError

    with pytest.raises(DataImportError):
        read_csv_robust(b"  \n\n  ", source_name="blank.csv")
